<script setup lang="ts">
import type { ApiEnvelope } from '~/types/api'
import type { Audit } from '~/types/billing'
import { money, billingDate } from '~/utils/billing'
definePageMeta({ layout: 'admin', middleware: 'superadmin' })
useSeoMeta({ title: 'Administration' })
const { request } = useApi()
interface Overview { customers:number; active_customers:number; active_subscriptions:number; expiring_soon:number; payments_this_month:{currency:string;amount:number}[]; stripe_enabled:boolean; recent_activity:Audit[] }
const { data, pending, error, refresh } = await useAsyncData('admin-overview', () => request<ApiEnvelope<Overview>>('management/overview'))
const stats = computed(() => data.value?.data)
</script>
<template><div><div class="flex items-start justify-between"><div><p class="eyebrow">Your business at a glance</p><h1 class="page-title mt-2">Overview</h1><p class="mt-2 text-text-secondary">Customers, subscriptions, and the activity that matters.</p></div><button class="btn-secondary" :disabled="pending" @click="refresh()">Refresh</button></div><LoadingState v-if="pending"/><div v-else-if="error" class="surface mt-6 p-6" role="alert">Unable to load the overview. <button class="text-brand" @click="refresh()">Try again</button></div><template v-else-if="stats"><div class="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><article v-for="[label,value] in [['Customers',stats.customers],['Active customers',stats.active_customers],['Active subscriptions',stats.active_subscriptions],['Expiring in 7 days',stats.expiring_soon]]" :key="label" class="surface p-6"><p class="text-xs font-medium text-text-muted">{{ label }}</p><p class="mt-3 text-3xl font-semibold tracking-tight">{{ value }}</p></article></div><div class="mt-6 grid gap-6 lg:grid-cols-3"><section class="surface p-6"><h2 class="font-semibold">Payment operations</h2><p class="mt-4" :class="stats.stripe_enabled?'badge-success':'badge-warning'">Stripe {{ stats.stripe_enabled?'enabled':'disabled' }}</p><p class="mt-3 text-sm text-text-secondary">{{ stats.stripe_enabled?'Customers can use Checkout for linked plans and manage their Stripe billing.':'Online payments remain unavailable until Stripe keys and webhook signing are configured.' }}</p><div class="mt-6 border-t border-border pt-5"><p class="text-xs text-text-muted">Manual payments recorded this month</p><p v-for="item in stats.payments_this_month" :key="item.currency" class="mt-2 text-2xl font-semibold">{{ money(Number(item.amount),item.currency) }}</p><p v-if="!stats.payments_this_month.length" class="mt-2 text-sm">No payments recorded</p></div><NuxtLink to="/admin/payments" class="btn-secondary mt-6">View payment records</NuxtLink></section><section class="surface p-6 lg:col-span-2"><div class="flex justify-between"><h2 class="font-semibold">Recent activity</h2><NuxtLink to="/admin/audit" class="text-xs text-brand">View audit log →</NuxtLink></div><div v-if="!stats.recent_activity.length" class="py-12 text-center text-text-muted">Your administrative activity will appear here.</div><div v-for="entry in stats.recent_activity" :key="entry.id" class="flex justify-between gap-4 border-b border-border py-4 last:border-0"><div><p class="text-sm font-medium">{{ entry.action.replaceAll('.',' · ').replaceAll('_',' ') }}</p><p class="mt-1 text-xs text-text-muted">{{ entry.actor?.name || 'System' }} · {{ entry.subject_type }} #{{ entry.subject_id }}</p></div><time class="shrink-0 text-xs text-text-muted">{{ billingDate(entry.created_at) }}</time></div></section></div><div class="mt-6 grid gap-4 sm:grid-cols-3"><NuxtLink v-for="[title,copy,to] in [['Manage customers','Review accounts and access','/admin/customers'],['Configure plans','Pricing, visibility, and limits','/admin/plans'],['Manage subscriptions','Assignments, periods, and status','/admin/subscriptions']]" :key="to" :to="to!" class="surface p-6 transition hover:border-brand"><h2 class="font-semibold">{{ title }} →</h2><p class="mt-2 text-sm text-text-secondary">{{ copy }}</p></NuxtLink></div></template></div></template>
